INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p987106-me322', 'stk-user5216', 'ME 322', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nجودة المقرر بشكل عام : سيء للاسف والسبب سوء اختيار الكتاب وطريقة ترتيب المواضيع الي شامله في المقرر\n\nالمواضيع التي يغطيها المقرر : التصنيع + التلحيم + ادواة القص + قوالب الصب + الطرق والضغط و الثني ( الي بتشابتر 6 و 7 و 9 ) وبشكل عام المنهج مو واضح والكتاب كذلك\nمع ان المواضيع شييييقه ومهمه لكن للاسف قسمنا messed up the course\n\nالكتاب المستخدم للمقرر : سيء جدا ++\n\nالأسئلة والأمثلة المستخدمة في المقرر : غييير كافيه وفيه نقص شديد\n\nطريقة دراسة المقرر :\n1 - سلايدات د خان ( موجوده فـ التراكر )\n2 - فهم الامثلة الي موجوده في الكتاب واعادة حلها\n3 - حل اسئلة الهومورك + الهوموركات القديمه ( موجودة في التراكر )\n4 - حفظ اسئلة الخيارات الموجوده في الاولد اقزاااامزز ( لانها تشكل 40% من الاختبار)\nوباقي 60 % راح تكون على المسائل وهذي تراجعلها من الهوموركات الحاليه والقديمة\n\n_ اضافة _\nلاب المادة ممتع لكن للاسف مو ماشي مع المادة يعني لما تاخذ ادواة القص مثلا تكون في الاب تشتغل على القوالب … والعكس وهالشي مو كويس لان المااادة تنفهم بشكل اسرع واسهل عن طريق التطبيق الي مره ثانيه قسمنا تجااهله\n\n, وبالتوفيق ,", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-322-manufacturing-processes/120747/2", "user": "user5216", "ts": 1329315046000, "tid": 120747, "pn": 2}}', 1329315046000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1076577-me322', 'stk-user5430', 'ME 322', 'info', '{"desc": "كورس مهم وتحس انه عملي كثير\n\nزي ما ذكروآ الشباب انه يتكلم عن التصنيع وكل عملياته وادواته من طرق و معدات\nووووووو إلخ\n\nالكورس ميزته ان مسائلة الكتابية سهله , و لكن فيه كمية معلومات كبيرة جدا جدا جدا\nفـ تضيع شويات في الاختيارات\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-322-manufacturing-processes/120747/4", "user": "user5430", "ts": 1344250604000, "tid": 120747, "pn": 4}}', 1344250604000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1228985-me322', 'stk-limitless', 'ME 322', 'info', '{"desc": "الكورس حلو وممتع , يعني يعرفك على أشياء كثيره في التصنيع وتعرف تفسير لبعض طرقها إلى كنت تشوفها ولا تفهمها .\n\nأفضل طريقة لدراسة المادة , بنسبة لي كنت أدرس من سلايدات سلمان باشا وكانت أكثر من ممتازه مع أسئلة الهومورك وأولد هومورك وكان وضعي أوكي إلى الفاينل كنت ما ادرس ألى قبل الإختبار بيومين وهذا الي خلاني أخذ قريد نازل بالنسبة لماده سهله ( b ) .\n\nأخر شي , الماده ممتعة وسهلة فلا تفرط فيها .\n\nموفقين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-322-manufacturing-processes/120747/5", "user": "limitless", "ts": 1369691821000, "tid": 120747, "pn": 5}}', 1369691821000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1229790-me322', 'stk-user8502', 'ME 322', 'info', '{"desc": "مادة تتكلم ع ن طرق تصنيع المواد وتغطيها كنظريات وكحسابات\nالاختبارات جزئين :\nnumerical 60%\nMSQ 40%\nالمذاكرة لهالمادة تحتاج شوية تخطيط … حاول تضبط المسائل وتفهمها مزبووووط وتاخذها من الاولد كوزز او الهوموررك بعد ماتخلص افتح السلايدات وافهم مضبووووط\n\nانا ما اعتبر المادة صعبة لكنها تحتاج تركيز", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-322-manufacturing-processes/120747/6", "user": "user8502", "ts": 1369845354000, "tid": 120747, "pn": 6}}', 1369845354000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1251056-me322', 'stk-s2010xxxxx', 'ME 322', 'info', '{"desc": "الماده هذي على حسب مدرسك , اذا كان كويس ويحل مسائل بتكون سهله معك اما اذا كان ما يحل مسائل فـ الله يعينك يا صاحبي. الماده فيها حفظ كثييييييير جدا وغثيثه شوي. لا تعتبرها ماده سهله او ماده قريد. الماده تحتاج شغل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-322-manufacturing-processes/120747/12", "user": "s2010xxxxx", "ts": 1375446160000, "tid": 120747, "pn": 12}}', 1375446160000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1373356-me322', 'stk-user2352', 'ME 322', 'info', '{"desc": "جودة المقرر بشكل عام\nالكورس مهم جدا لطلاب الهندسة الميكانيكية باعتباره\nعمليات تصنيع … Manufacturing processes\nولطلاب الهندسة الصناعية باعتباره\nتقنيات تصنيع Manufacturing TECHNOLOGY\n\nالمواضيع التي يغطيها المقرر\nCasting , machining , welding , bulk deformatin , sheet matal forming\nمقدمة لعمليات التصنيع وخصائصها المؤثرة علي اعتبارات التصميم والجودة والتكلفة ؛ تحليل الأداء والجهد وخصائص المادة المطبقة لأساليب تشكيل المواد ؛ عمليات تشغيل الألواح ؛ السحب والسحب العميق ويشمل الانحناء والدرفلة والثقب ؛ عمليات السباكة وحساباتها ؛ عمليات اللحام والوصل.\nآلية قطع المواد ؛ عمليات إزاحة الرايش ؛ المواد والشكل الهندسي لأدوات القطع وأساليب تجميعها ؛ تأثير متغيرات القطع علي عمليات التشغيل و أجزاء ماكينة القطع ؛ عمليات التشغيل الغير تقليدي ؛ اختيار الأساليب وتتابع العمليات.\n\nالكتاب المستخدم للمقرر\nModern Manufacturing processes\nوالكتاب ممتاز وواضح وهو أفضل مرجع للمذاكرة والفهم\n\nنصيحة : لا تضيع وقتك على أي سلايدات إلا بعد قراءة الكتاب لأن بعض السلايدات ما تشرح الكونسبت بالتفصيل\nأو ذاكر من سلايدات الدكتور خان والدكتور محي الدين أحمد بعدين اقرأ الكتاب وحدد على الكلام المهم والقوانين\nوحل مسائل الكتاب خاصة الهوموركات الجديدة والسابقة\nومسائل الدكتور محي الدين أحمد للهلب سيشن مفيدة\nوالكورس يحتاج لمتابعة وقراءة مع فهم الأمثلة وحل المسائل وفهم الصور والرسومات من الكتاب فحاول تستخدم الألوان في تحديد الأجزاء المهمة،،\n\nالأسئلة والأمثلة المستخدمة في المقرر\nالكتاب الجديد شامل وفيه كل المعلومات الكافية والمطلوبة ومدعم مع الأمثلة والمسائل الشاملة لكل جزء\nودائما الإختبارات 60% مسائل\n40% كونسبت نظري على شكل اختياري أو فراغات أو صح وخطأ\nمدى فائدته في الناحية التطبيقية\nالكورس مفيد كما ذكرت لطلاب الميكانيكال والإندستريال خصوصا للذين يرغبون بالتطبيق في شركات انتاج صناعية مثل شركة GE وشركة التصنيع\nراح تشوف الكثير من اجزاء هذا الكورس على وجه الواقع\nواللاب 323 مفيدج جدا وممتع راح تتعلم في الكثير من المهارات مثل تقنيات اللحام والتصنيع وغيرها وتحاج الى لبس بالطو مع SAFETY SHOES فحاول تستفيد منه\nالسلبس الجديد في المرفقات 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-322-manufacturing-processes/120747/21", "user": "user2352", "ts": 1401289152000, "tid": 120747, "pn": 21}}', 1401289152000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1381734-me322', 'stk-abo_ali', 'ME 322', 'info', '{"desc": "جودة المقرر بشكل عام\nاشوف انه ممتاز ماغير انه طووووووووووويل مره 10 شباتر كل واحد يقول الزود عندي ,\n\nالمواضيع التي يغطيها المقرر\nانواع التصنيع -المعادن- لانه ما تطرق لطرق تصنيع الاكل او غيره فقط اختصرها في المعادن\nانواع التجميع\n\nالكتاب المستخدم للمقرر\nما اذكر وشسمه , لكن جيد , في نفس الوقت طويييييييييل مره 😦\n\nالأسئلة والأمثلة المستخدمة في المقرر\nجدن ممتازه , اذا صفيت عليها فأنت في الوضع السليم\n\nمدى فائدته في الناحية التطبيقية\nممتاز جدن , لمن تشوف كثير من العمليات راح تكون صوره عن كيفية صناعة الكثير من الامور اللي حولك 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-322-manufacturing-processes/120747/22", "user": "Abo_Ali", "ts": 1403435152000, "tid": 120747, "pn": 22}}', 1403435152000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1449998-me322', 'stk-dyaa94', 'ME 322', 'info', '{"desc": "152\n\nماده ممله لأبعد الحدود…وماهي مادة قريد انسى…يبغالها جهد ومذاكرة…ماحبيتها\n\nطبعا في المياجر يجيبوا اسئلة مامرت عليك تختلف عن الواجب واللي يشرحها الدكتور…عشان كذا حاول تفهم الدروس صح قبل ماتخش الاكزام\n\nللي مايبي يذاكر الكتاب…انصحك بسلايدات ابودير ((دور الجديده))…اشوفها شامله ومرتبة و90% من الاسئلة حقت الخيارات موجوده في السلايدات…\n\nولأنه القريدنق اللي مشا عليه دكتورنا كان ستاندرد القريد ابد ماكان مرضي…عشان تجيب البي وأكثر تأكد انك تجيب كل درجاتك +80 …\n\nME307 ارحم قلب ههههه…اللاب حقها حلو though وسهل تجيب فيه قريد…\n\nبالتوفيق يا KFUPMEerzzzzzz…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-322-manufacturing-processes/120747/25", "user": "Dyaa94", "ts": 1463913538000, "tid": 120747, "pn": 25}}', 1463913538000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1524151-me322', 'stk-feras-mtn', 'ME 322', 'info', '{"desc": "Term 193\n\nجودة المقرر بشكل عام:\nمهم جدا لطلاب الميكانيكال …\nوللاسف متعمق اكثر في جزئية الميكانيكال اكثر من الاندستريال … لكن شي جميل تاخذ فكرة عامة عن الManufacturing processes كطالب اندستريال\n\nالمواضيع التي يغطيها المقرر:\nCH1: Introduction to manufacturing\nCH7+8: Metal Casting Fundamentals & Processes\nCH25+26: Joining and Fastening Processes - Welding\nCH17+18+19: Material Removal Processes\nCH14: Fundamentals of Metal Forming\nCH15: Bulk Deformation Processes\nCH16: Sheet Metalworking\nبنفس الترتيب واتوقع في الترم الصيفي الكتاب يختلف عن كتاب الاترام العادية مو متاكد\nلكن كتابنا اسمه (M. P. Groover, Principles of Modern Manufacturing: Materials, 5th Edition John Wiley & Sons, Singapore, 2011.)\n\nالكتاب المستخدم للمقرر:\nللاسف الكورس كان اون لاين وما اتوفر لنا نسخة الكترونية\n\nأخرى:\n-بتكلم بشكل عام بحكم اني خذيت الكورس اون لاين ويختلف تماما عن الاترام العادية …\n-حل الهوم ووركات والاولد اكزامز وكذا بتضمن النيوميركال بارت…\n-الكورس فيه كمية حفظ معلومات مو طبيعية …\n- حاولت ادور في اليوتيوب على اي قناة شروحات للكورس وماحصلت الا هذي واشوفها كويسة\n\nhttps://www.youtube.com/watch?v=jdFrBtHeJbs\n\n-الكورس افرجه B … والB في ترمنا كان من 77 وعلى كلام شباب اخذوها في ترم 191 كان برضو الB من 77 وزيد 5 درجات على كل قريد … وبشكل عام الكورس يبيله جهد اكثر وبالتوفيق للجميع", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-322-manufacturing-processes/120747/27", "user": "Feras-MTN", "ts": 1595595676000, "tid": 120747, "pn": 27}}', 1595595676000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1527299-me322', 'stk-guest', 'ME 322', 'info', '{"desc": "T201\n\nالمادة كريهة فيها كمية معلومات مهولة\nبما أن الوضع أونلاين فسمحوا لنا نفتح السلايدات والكتاب وقت الاختبار.\n\nالاختبار قسمين\nاختيارات Theory\nNumerical تحل فورقة وبعدها تصور حلك وترفعه عالبلاكبورد\n\nمع ان الاختبار كان open slides open notes إلا أن الآفرج للقسم الأول 20 من 30 فلك أن تتخيل صعوبة الأسئلة عزيزي القارئ.\nاما بالنسبة لقسم النيوميركال فكان متوسط الصعوبة فالميد والآفرج حول 24من30\n\nالفاينل نفس الميد بالضبط.\n\nطريقة المذاكرة سلمكم الله… سلايدات مبين للكونسبت وسلايدات سرحان للنيوميركال وحل الهوموورك بنفسك وأضمن لك تجيب درجة زينة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-322-manufacturing-processes/120747/29", "user": "Guest", "ts": 1608989588000, "tid": 120747, "pn": 29}}', 1608989588000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1276573-me322', 'stk-mr-3b0d', 'ME 322', 'info', '{"desc": "هذا رابط سلايدات خان ممتازة :\n\nhttps://www.dropbox.com/s/xkma3nud8iwza0l/ME206_Dr.Khan.zip\n\nطبعاً السلايدات طويلللة مرررة, فاللي بتسويه انك تقرا السلايدات قرائة سريعة عشان تعرف وش السالفة ووش يتكلم عنه التشابتر وكذا ,\n\nبعدها انتقل على طول لأسئلة الهومورك والكويزات, بتلقى ان القوانين الي تستخدمها محدودة في كل تشابتر فاللي تسويه انك تحفظ هالقوانين وطريقة تطبيقها وتحل اسئلة الهومورك والكويز-في قوانين كثيرة ما تجيك بمسائل بالرغم انها موجودة بالسلايدات هذي اسحب عليها-\n\nإذا عرفت الطريقة 100% وحليته بفهم بإذن الله انت ضمن 60% من الاختبار\n\nال40% الثانية عبارة عن ملتبل تشويس فحاول تذاكر السلايدات قد ما تقدر وإذا فيه اولد اقزامز ولا كويزات اختيارات ترى تفيدك جداً\n\nوبالتوفيق…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me322/151030/3", "user": "mr-3b0d", "ts": 1382456204000, "tid": 151030, "pn": 3}}', 1382456204000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1287265-me322', 'stk-user5800', 'ME 322', 'info', '{"desc": "العادة ان الدكتور انور شيخ يحاضر عن هذه المادة\nولكن يبدو انه ما هوب حولها السمستر القادم 132\n\nعموماً ، من واقع تجربة في مادة me309\nد. شفيق خان متميز في تلخيص المقررات و المحاضرات كويزاته عبارة عن تيك هوم\nيشرح المسائل بكل وضوح ، فبالتالي تفهم معه على طول من ناحية الاجزاء الحسابية.\nواما الاجزاء النظرية ، فانا ارى انها تنعكس على مجهود الطالب في المذاكرة وقراءة الكونسبت\nسواء من الكتاب او من اي سورس خارجي آخر\n\nوبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me322/152032/7", "user": "user5800", "ts": 1384443056000, "tid": 152032, "pn": 7}}', 1384443056000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1428423-me322', 'stk-bora3d-2', 'ME 322', 'info', '{"desc": "وملاحظة حلوة تفيدكم ياشباب وهي بعد ماتخلص كل شابتر روح لأسئلته الكونسبت في الكتاب وحلهم ، هم قسمين أسئلة حسابات وأسئلة كونسبت يعني كلام فقط شي حلو لو تحلهم عشان تتأكد من ثبات المعلومة وأيضاً تركز على المعلومات المهمة ألي تجيك في الكويز أو المياجر ، مجدداً بتوفيق شباب 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me322/170032/2", "user": "bora3d-2", "ts": 1442137700000, "tid": 170032, "pn": 2}}', 1442137700000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1099635-me322', 'stk-ibra1991', 'ME 322', 'info', '{"desc": "يأ اخوان المدرس يشرح من سلايدات مو متوافقه مع الكتاب (يعني اول شابت لازم ناخذه حسب\nالسيلابس هو شابت ثمانية و اول درس من الشابتر حسب الكتاب هو درس الاورثوقنال كاتينق عكس السلايدات\nالي يكون فيها الدرس الاخير ) وحملت سلايدات دكاترة ثانين وحصلت نفس الشي\nغير ان فيه دروس بالكتاب مو موجوده بسلايدات الدكاترة ولا بسلايدات مدرسنا ولا شرحها وبالسيلابس مو مذكور انها محذوفه .\nنتمنى احد يفيدنا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me322/132687/1", "user": "ibra1991", "ts": 1348780651000, "tid": 132687, "pn": 1}}', 1348780651000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1099641-me322', 'stk-metallic', 'ME 322', 'info', '{"desc": "المادة هذي اسمها وسّع صدرك … أنت أهم شيء إعرف القوانين وحل مسائل الأولد اكزام والهوموورك (وتراها قليل ومتكررة) ألحين أنت ضمنت 60 بالمية من الميجر … باقي 40 بالمية … 20 سؤال ملتبل تشويس … نصفها لو تمر السلايدات مرور الكرام بتضمنها … الصعوبة فقط بالـ 10 أسئلة الأخيرة (20 بالمية من الميجر) …\n\nوترا الكتاب ما أخبر أحد كان يذاكر منه … لذلك، اذا على كلامك أنك ذاكرت سلايدات دكتورين (مختلفة) فأنت ماشاء الله غطيت المنهج بالنسبة للملتبل تشويس … ترا الكورس سهل ومياجره عادةّ متوسطة الى سهلة (خصوصاً الجزء النوميركال) ، بس الواحد يشيل هم اذا كثرت عليه السلايدات ، وهي بالنسبة لي أكثر مادة طمّرت بسلايداتها لأن الأسئلة عادةً تكون سطحية أكثر من أنها تكون من بين السطور …\n\nموفق … 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me322/132687/2", "user": "METALLIC", "ts": 1348781833000, "tid": 132687, "pn": 2}}', 1348781833000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1099740-me322', 'stk-user8509', 'ME 322', 'info', '{"desc": "انتبه من الاولد اقزام لانهم من سمسترين تقريبا بدوا يشرحون المنهج من شابتر 8 عكس الاترام اللي قبل كانوا يبدون بشبتر 1 مافيه الا اولد اقزام واحد الا موجود وهو حق ترم 111 دور له بارشيف المنتدى تحصله اذكر انه جاء حوالي 11 او 12 خيار بالنص منها وهي كانت 20 خيار وحاول تذاكر كويزات انور الشيخ خصوصا الخيارات لانه يجيبها بالنص من كويزاته بالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me322/132687/7", "user": "user8509", "ts": 1348818325000, "tid": 132687, "pn": 7}}', 1348818325000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
