INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1153586-me322', 'stk-metallic', 'ME 322', 'srcP', '{"html": "حاولوا تجمعون كويزات متيريل الفاينل من طلاب أنور الشيخ … مهمة جداً جداً جداً …<br><br>أنا عندي كم كويز لأنور الشيخ (موجوده بالمرفقات) بس أني ما أدري هل هي لماتيريل الفاينل ولا لا …<br><br>عموماً ، أذكر أنه كان يجينا منها ملتبل شويس كثير … فاحرصوا عليها …<br><br>موفقين … 🌹<br><br>​<span data-fid=\"stk-f1153586-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1153586-0": {"name": "ME322-FINAL-AnwarSheikhQuizzes.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/e770e250114d0b213867b79265568a95c869aa17b930389ea3743381182a1d28"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/final-old-exams-for-me322/137445/4", "user": "METALLIC", "ts": 1357158504000, "tid": 137445, "pn": 4}}', 1357158504000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
