INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p990597-me322', 'stk-mezo.m', 'ME 322', 'srcP', '{"html": "يا شباب هادا الهومورك نفسه من سمستر ماضي … انصحكم تحلوه وما تنقلوه … عشان تستفيدو لأنه المياجر قربت … دعواتكم 🙂<br><br>​<span data-fid=\"stk-f990597-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f990597-0": {"name": "HW# 5-092-solution.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hw-me-322-or-206/121454/5", "user": "mezo.m", "ts": 1329837657000, "tid": 121454, "pn": 5}}', 1329837657000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
