INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1037796-me322', 'stk-user2352', 'ME 322', 'srcP', '{"html": "Final exam formula sheet<br><br>الفورملا شيت يا شباب في المرفقات وتحتاج للترتيب لأنها موزعة في الملفين المرفقين 🤠 ( فقط CH 2 &amp; 6 &amp;7 هي ماتيريال الاختبار النهائي،، وقد تم التأكد من الخبر على كلام دكتورنا إن CH#5 غير مشمول في النهائي وفألكم التوفيق:) 🌹/<br><br>​<span data-fid=\"stk-f1037796-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f1037796-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br>​<span data-fid=\"stk-f1037796-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1037796-0": {"name": "FormulaSheet_Final.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/d30de06428f8ad3ae07e51d33ae69eac699e746ac8bbd4be403acbe8a13ec6a3"}, "stk-f1037796-1": {"name": "FormulaSheet_Exam2.pdf", "v": "data:application/pdf;base64,"}, "stk-f1037796-2": {"name": "FORMULA ME322.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/1bc27cbeb3be1f498b5199b419927210e2b228a29b2bbf5098ed7c7b657936d1"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-322-final-exam/125573/14", "user": "user2352", "ts": 1337092133000, "tid": 125573, "pn": 14}}', 1337092133000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1103626-me322', 'stk-oz-99', 'ME 322', 'srcP', '{"html": "هذا السلوشن حق الهوموورك الاول للسمستر الماضي 🌹<br><br>​<span data-fid=\"stk-f1103626-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1103626-0": {"name": "HW1.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/c2d944c7408d639e79da69ae5fb4612d27fbbb75e1ebf62562fe224fd52d31e4"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me-322/132942/27", "user": "oz-99", "ts": 1349465677000, "tid": 132942, "pn": 27}}', 1349465677000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-illusions-me322', 'stk-illusions', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98206", "n": "Dr. Muzafferuddin Mahmood", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Me322\nTerm:172\n\nالتحضير : يومي ينادي على الاسماء , بعد خمس دقايق وبنهاية الكلاس ينادي على الي ما جو ببداية الكلاس ولا يرفع راسه وهو ينادي فواحد يحضر ثلاثه عادي.\n\nطريقة الشرح : سلايدات والماده نظرية بشكل مقرف , يعني كل شابتر بس فيه ثلاث امثلة ولا اربعه وهو يشرح كل الامثلة بس باقي الوقت على السلايدات , فالمسائل بسيطة والباقي نظري فما كنت اركز معه مره.\n\nالكويزات : عطانا خمسة مدري سته وحذف اسوأ واحد وكلهم تقريبا مره مشابهين للامثله واذا مره شطح جاب سؤال يشبه الهوموورك مره.\n\nالمياجر: كومن\nالفاينلات :كومن\n\nالقريد النهائي: B+\n\nالصوت: واضح بس الاكسنت مش ولا بد , بعض الاحيان اقول له شي وانا واقف قدامه ويبدا يكلمني ولا افهم له من الاكسنت الغريبة .\n\nإضافات : المدرس طيب طيب طيب طيب , تصحيحه اشوفه كويس , كنت اذا راجعت ميجري انصدم من بعض الاشياء شلون معطيني عليها درجات ومع ذلك اذا ناقشته كان يزيدني درجه ودرجتين , شرح عشان ما اظلمه ما كنت اركز معاه , بس المادة اغلبها حفظ والمسائل حقتها سهله ولا يلعبون فيها واجد , وهو نظامه اقعد واكفني شرك انا بكفيك شري , يعني اقعد على الجوال وساكت عادي بس لا تنام اهم شي . فاذا تبي ترتاح بالكلاس وخصوصا ان المادة ما يبيلها ذاك الشرح هو الخيار المثالي , مع انه افرجنا كان حول الثمانين بكل شي ومع كذا ما خلا الافرج بي خلاه سي بلس. بس بشكل عام المدرس تصحيحه كويس واخلاق اتوقع هو اطيب واحد بالجامعة كلها فأشوف لا تفوته اذا كان موجود.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1497908-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muzafferuddin-mahmood/98206/17", "user": "ILLUSIONS", "ts": 1534589500000, "tid": 98206, "pn": 17}}]}', 1534589500000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11264-me322', 'stk-user11264', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98206", "n": "Dr. Muzafferuddin Mahmood", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME322 - 201\nأونلاين بالكامل\n\nالتحضير: غالبًا آخر الكلاس، ينادي على الأسماء.\nطريقة الشرح: يتلو تلاوة عطرة من السلايدات، والمسائل يقراها قراءة حتى ما يحلها قدامنا. ما أستفدت من شرحه نهائيًا!\nالكويزات: كانت الكويزات كثيرة نظرًا لطبيعة هذا الترم. نصف منها خيارات وكونسبت ونصف منها حل مسائل، تقدر ترفع حلك ويعطيك بارشل كريدت. بالنسبة للكونسبت أحيانًا يجيب أسئلة من برا الشابتر ولمن واجهناه قال عادي هذي surprise questions!! يهووووووه تمقلبنا انت ولا وش ترا مو فلوق يوتيوب … عمومًا إذا سواها حاولوا تضغطون عليه عشان يعوضكم بالدرجات حق الأسئلة الزايدة. بالمناسبة في الأخير ما حذف ولا كويز\nالمياجر والفاينلات: كومن. تصحيحه يدف دففففففف شديد وأشوفه حلو، بس الكورس آفرج بالنهاية فحط هالنقطة ببالك… لو ارتفع آفرجكم بالأخير انتم المتضررين (هالشيء صار بترمنا، الآفرج بالأخير طلع 77 وأظنه كان C+، مو B مثل ما يقول البعض)\nالقريد النهائي: C\n\nإضافات:\n- الدكتور طيب جدًا وحليل\n- مشكلته ما يرد على الإيميلات ومزاجي من هالناحية… يجلطك جلطة مب صاحية إذا تبي منه شغلة\n- شخصيًا ما ناسبني أبدًا في الأونلاين. فايدتي من شرحه كانت صفر. إذا تدور الفائدة دوّر غيره.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527813-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muzafferuddin-mahmood/98206/18", "user": "user11264", "ts": 1610433379000, "tid": 98206, "pn": 18}}]}', 1610433379000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-turky_al-dossary-me322', 'stk-turky_al-dossary', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98220", "n": "Dr. Shafique Khan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "~~~~ ME- 322 / 206 … Term: 121 ~~~~\n\nالتحضير :\n\nينادي بالاسماء اخر الكلاس ،، عادي تتاخر 🚬\n\nطريقة الشرح :\n\nيقرأ من السلايدات ،، بس يتكلم في المنهج ،، اذا فهمت على كلامه وقدرت تسمعه تفهم مزبوط 😐\n\nالكويزات :\n\nعطانا كم كويز اون لاين ،، وكم كويز نحله في البيت وسهلة ،، ولا كويز حليناه في الكلاس 👍\n\nالمياجر:\n\nكومن ،، ومقسوم قسمين :: 40 % كونسبت ،، 60% نيوميركل\n\nوطبعا كثير مكرر من الاولد الاكزام ،، والنيوميركل لازم تجيب فل مارك 🥊\n\nالفاينلات :\n\nنفس نظام المياجر ،، ولاتنسى عليه 40 % يعني شدة حيل 😭\n\nالقريد النهائي:\n\nA 🌺\n\nالصوت :\n\nوحده من سلبياته ،، بس اقعد قدام ،، وامورك طيبة\n\nإضافات :\n\nمدرسين المادة ذي اهم شيء تصحيحه ،، اما شرح المادة ما يحتاج لانها ما غسر قراية من الكتاب\n\nفدور على المدرس اللي يساعد في التصحيح والقريدات\n\nشفيق خان ممتاز في التصحيح وابد خله يعرف اسمك ولا تتاخر تراه ما يقول شيء بس يحقد ولا تلعب بالجوال لانه يتذكر الطلاب\n\n___________________________________________\n\nاي سؤال ،، لا يردك الا رسالة خاصة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1162336-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-shafique-khan/98220/14", "user": "Turky_Al-Dossary", "ts": 1357925558000, "tid": 98220, "pn": 14}}]}', 1357925558000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8551-me322', 'stk-user8551', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98228", "n": "Dr. Anwar Khalil Sheikh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 322 - Term 122\nدكتور أنور شيخ (الدكتور هندي أو باكستاني ، مهوب عربي مثل ما يوحي إسمه)\n\nالتحضير : بآخر الكلاس ، ما يحاسب عالتأخير أبدا ، متســـــاهل بالتحضير بشكل فظيع .\nكلاسنا كان يبدأ 9:00 و ما تلقى فيه إلا 5 طلاب بالكثير ، إذا جات الدقيقة 45 يبتدون يدخلون الطلاب إلى ما يمتلي الكلاس.\nيحضر بالإسم على ملف إكسل معروض بالبروجكتر ، ما يخصم بآخر الترم عالغياب ، غالبا ما يحضر -هو- متأخر للكلاس.\n\nالشرح : ســـئ جدا ، يفتح السلايدات و يقعد يتكلم و ما أحد حوله ، الشعب يا يلعبون بجوالاتهم أو يسولفون مع بعض (لو حضروا طبعا).\nيبدأ يشرح الجزء النظري لكل تشابتر ثم إذا خلص منه يحل بعض المسائل ، صعب إنك تنتبه معه لأنه دائما ما يخطئ .\nلو كنت بأقيم شرحه راح أعطيه 2 من 10 ،الملفات اللي يحطها عالويب سيتي جيدة.\n\nالكويزات : مكررة من الأترام السابقة (يحط الكويزات القديمة بالويب سيتي) ، سهل إنك تجيب فيها قريد طيب.\nيعطيكم 5 كويزات بالترم تقريبا (واحد منهم عالويب سيتي) و يحسبهم كلهم.\n\nالتصحيح : نظرة سريعة عالسؤال و يعطيك قريد (يعني ما يتابع الخطوات) ، لو كان السؤال من 5 فنادر ما يخصم أكثر من 1 حتى لو حلك غلط ، يشوفك كاتب قوانين و مسوي عمليات حسابية راح يعطيك أكثر من نص القريد عالسؤال.\n(الدكتور نظره ضعيف فصعب إنه يتابع خطوات الحل)\n\nالقريدات : هذي الإيجابية اللي تطغى على كل مساوئ الدكتور ، الدكتور ما يدف إلا يشوت بالقريدات 😁.\nأكثر إنسان شفته يدف هو أنور شيخ ، أتوقع إن أفرج سكشنا كان B+ ، أنصح إنك تنزل معه لو كان عندك مواد ثقيلة بالترم ، راح تنسى مادته.\n\nالصوت : يخدر الرأس 🤠.\n\nإضافات :\n- نادر التواجد بمكتبه ، و حتى لو كان موجود يقفل عليه الباب و ما يفتح لك إلا بطلعة الروح.\n- يتأخر كثير بتصحيح المياجر ، أذكر الميجر الأول أخذناه بـ 6 مارس و رجعه لنا بـ 8 أبريل !\n- لو تأخرت بتسليم الهوموورك راح يخصم عليك نصف الدرجة.\n- متساهل بالميك أب ، و أخلاقه طيبه.\n- عينه الصحيحة هي اليسار.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1237397-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-anwar-khalil-sheikh/98228/16", "user": "user8551", "ts": 1371927319000, "tid": 98228, "pn": 16}}]}', 1371927319000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9213-me322', 'stk-user9213', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98228", "n": "Dr. Anwar Khalil Sheikh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 322 - 161\n\nالتحضير :\n\nيوميا اخر الكلاس , اتوقع عنده غيابين فري بس لازم تتأكد لأن حسب المادة و الترم.\n\nطريقة الشرح :\n\nسلايدات يقراها قراءة عادية و يسوي سكيب لبعضها , الخلاصة ما راح تستفيد اي شي من حضورك للكلاس شف لك شي مفيد تسويه يا أما تقرا الكتاب حق المادة او تتدرب على اسئلة لأنك حرفيا ما راح تستفيد أي شي والمادة عموما سيلف ستدي ولكن شي حلو لو تكون عندك خلفية عن اللي بتقراه فالكتاب.\n\nالكويزات : عادية و كلها كانت مسائل اولد اقزامز اللي هي يسيطة اصلا.\n\nالمياجر: كومن.\n\nالفاينلات :كومن وكان اصعب من المياجر شوي.\n\nالقريد النهائي: C بس الدكتور ما يهم عموما.\n\nالصوت: عادي.\n\nإضافات :\n\nالمادة ما تحتاج دكتور شريح بس الدكتور هذا يعيبه مو منظم و كبير بالسن يعني تنتظر وقت طويل تعرف الاشياء المهمه بالكورس مثلا ماتيريال المياجر و الهوموركات و اوقات الكوزات. هو عادة يدرس ME406 بس ما ادري وش وضعه فيها. اذا مافيه الا هو نزل معه و سو اللي قلت لك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467256-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-anwar-khalil-sheikh/98228/24", "user": "user9213", "ts": 1485737548000, "tid": 98228, "pn": 24}}]}', 1485737548000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-king_of_c-me322', 'stk-king_of_c', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98229", "n": "Dr. Abdelrahman N. Shuaib", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(والله اني ما قيمت الا وانا عارف اني محاسب يوم الدين على ما اكتب)\n\nME322 سابقا ME206\nبنود التقييم :\nلاتنزل عنده\nالتحضير :\nلاتنزل عنده\nطريقة الشرح :\nلاتنزل عنده\nالكويزات :\nلاتنزل عنده\nالمياجر:\nلاتنزل عنده\nالفاينلات :\nلاتنزل عنده\nالقريد النهائي:\nبرا الجامعه واي جامعه.\nالصوت:\nلاتنزل عنده\nإضافات :\nانا دفعة 28 والله فاك الحساب في sKFUPM عشان اقيم هذا الدكتور. اشتغلت على المادة ف ميجر1 شغل خيالي, كنت اخذ الكتاب معايا القهوة, و قبل الميجر باسبوعين وانا اجهزله, وادخل الاختبار واحل اسئلة الاختيارات كلها صح الا واحد, واسئلة الحساب غلطت في سؤال واحد لا شفته في هوم وورك ولا في الاكزامبل حقت الكتاب, كان السؤال من اللاب اتذكرته بعد الاختبار والتكنيشن هوا اللي شرحه. وكلمت الدكتور على السؤال حق الخيارات وقلتله السؤال غلط ما رضي يقتنع وقالي روح راجع وكلمني, ورجعتله بعدها وقلتله السؤال غلط يا دكتور قال السؤال مو غلط وهو ماهو عارف انا اتكلم عن اي سؤال قلتله طيب ابغا ورقة الميجر حقي عشان اراجعها معاك, قال ماتشوف ميجرك, قلتله ورقه ماهي محلوله عشان نتناقش, قال(لا,عندك شي ثاني؟؟) وسار يطقطق على الكمبيوتر حقه, وبعدها ما اتذكر اني فكيت الكتاب وطلعت C في النهايه. الله يكافيه وين ما ودا وجهه ويشوفها ف عياله وعيال عياله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1291269-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-abdelrahman-n-shuaib/98229/8", "user": "KING_of_C", "ts": 1384979301000, "tid": 98229, "pn": 8}}]}', 1384979301000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_yazeed6-me322', 'stk-abo_yazeed6', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98232", "n": "Dr. Tahar Laoui", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور بصراحة ما هو متمكن من me 322 اللي هي عن manufacturing ,يعني أشوفه مبدع في مواضيع me 216 ودايم يربط المواضيع اللي ناخذها في me 322 بمواضيع ذاك الكورس واستحضاره جيد في هالمجال,لكن لو أحد يحشر له في me 322 يضيع ويصرف ,يعني أحسه حافظ اللي بالسلايدات لكن مو فاهمه مضبوط.\n\nالدكتور شديد بالتحضير ,ما عمره نسى التحضير ,أقول هالكلام لأني ما قد غبت عنده\n\nسلايداته تمشي الحال ,لكن أنصح أنك تخلي الكتاب جنبك وأنت تذاكر من سلايدته ,لأنه أشياء كثيرة ومهمة ما هي موجودة في السلايدات ,وأشياء كثيرة ما لها علاقة بالكورس “الظاهر من الكتاب القديم للمادة” موجودة في سلايداته وتضيع وقتك لو قريتها ,ولو تعتمد على الكتاب وتسحب على السلايدات أفضل لك ,والكتاب أشوفه جيد وشرحه واضح ,وأسئلة كثيرة في الامتحانات أتذكرها من شرح الكتاب.\n\nتصحيحه حقاني ,وحاول توضح كل شيء ,لأنه بيعطيك اكس كبير لو حطيت الأجوبة بدون ما تكتب القوانين وتطلع النواتج غلط.“هو بنفسه بينبهكم على النقطة هذي”\n\nبالنسبة للقريد ,فبالنسبة لي كان القريد اللي أعطانياه مرضي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1420409-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-tahar-laoui/98232/13", "user": "abo_yazeed6", "ts": 1421613019000, "tid": 98232, "pn": 13}}]}', 1421613019000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8219-me322', 'stk-user8219', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98232", "n": "Dr. Tahar Laoui", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me 322 term 142\n\nالتحضير: يومي أول 10 دقايق\n\nطريقة الشرح: حللللوة ماشالله\nمع إنها مادة مرة غثيثة لكن الدكتور يشرحها بطريقة ممتعة\nيمر سريع على المعلومات العادية\nوالكونسبت (المسائل) يركز عليها ويساعدنا نحلها، تجي للهوموورك والميجر بس تحتاج تقرأ شوية\n(المسائل 70% من الاختبار)\nوالجزء الحفظي يقولنا نجيب الكتاب ونخطط عليه عشان يسهل هذا الجزء\n\nالصوت: واضح\n\nالتصحيح:\nيركزز على اليونيتس مررررة\nوينبه على دا الشي!\nالتصحيح عادي زي أغلب الدكاترة إلي مروا عليّ\nنقطة مهمة جدا\nأحيانا تنسى قانون في أول المسألة ويعتمد على ناتجه باقي المسألة (القونين مرة كثير)\nفهو يقول إذا ماعرفت تطلع قيمة شي افترض القيمة\n\nيعني مثلا المطلوب: u\nu= a*b*c\nإنت نسيت كيف تجيب c\nافترض قيمة c أي رقم أو حرف حتى وكمل الحل\nلا تترك شي تعرفف تحله فاضي، بيعطيك على كل شي درجة!\nهو ينبهنا على هذي النقطة!\n\nالقريد النهائي: A++++++++++++++++++++++++++++++++++++\n\nدكتور حبيييييييييييييييييب وأخلاقه قمة قمة وبشووووش ماشالله ومرررررررة يهتم بمصلحة الطالب ويساعده قد ما يقدر ❤️ ❤️ ❤️\nويدففففف في القريد النهائي\n\nمرة أنصح بيه ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1424526-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-tahar-laoui/98232/14", "user": "user8219", "ts": 1439977737000, "tid": 98232, "pn": 14}}]}', 1439977737000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-s2010xxxxx-me322', 'stk-s2010xxxxx', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98233", "n": "Dr. Numan Abu-Dheir", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me 322 ترم 123\nاكثر كلاس ممل ممكن يمر عليك بالجامعه الكلاس حقه , وماده الـ 322 تحتاج حل مسائل, 60% من الاختبارات تكون مسائل وانتهى الترم كامل وهو ما حل الا يمكن 5 او 6 مسائل. ما يحل مسائل ابدا! والشي هذا بينكبك. واحيانا كثيره تكون اخلاقه سيئه جدا وممكن يهينك قدام الطلاب لانك سالته سؤال شرحه قبل! توقع انه بيرفع صوته وبيطقطق عليك. لا انصح بهذا الدكتور ابدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1251055-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/numan-abu-dheir/98233/16", "user": "s2010xxxxx", "ts": 1375445977000, "tid": 98233, "pn": 16}}]}', 1375445977000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8512-me322', 'stk-user8512', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98233", "n": "Dr. Numan Abu-Dheir", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me 322 ترم 123\n\nكلاس ممل جدا جدا…يهتم بالكونسبت مع انه 60% من المياجر على المسائل الحسابية…\nطبعا التحضير عنده طامة…مايعترف بالتأخير غياب على طول …\nومزاجي يوم يحضر اول خمس دقايق ويوم يحضر بعد 20 دقيقة!\nمتعاون في الاوفس\nوكوزاته متوسطة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1251750-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/numan-abu-dheir/98233/17", "user": "user8512", "ts": 1375773263000, "tid": 98233, "pn": 17}}]}', 1375773263000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2352-me322', 'stk-user2352', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98233", "n": "Dr. Numan Abu-Dheir", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Me322\n\nالتحضير : بداية الكلاس واحيانا اخر الكلاس\nطريقة الشرح : سلايدات مع توضيح على السبورة\nالكويزات : صعبة شوي ويسمح بفتح الكتاب\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: B\nالصوت: واضح\nإضافات : الدكتور يهمه مصلحة الطالب ويزعل اذا ما احد شارك معه وميزته يحل مسائل اضافية ومتساعد في الاوفس أور للطلاب الجادين اللي يبون الفهم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1295340-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/numan-abu-dheir/98233/18", "user": "user2352", "ts": 1385542905000, "tid": 98233, "pn": 18}}]}', 1385542905000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-handsome_thief-me322', 'stk-handsome_thief', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98233", "n": "Dr. Numan Abu-Dheir", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Me 322 sem#123\n\nالتحضير : ما أذكر صراحه بداية الكلاس وﻻ نهايته لأني دايماحضر بع 10 او 15 دقيقه من بداية الكلاس بس دايم كان يحضرني\nالشرح: كنت أنام طول الكلاس وﻻ أدري وش يقول بس صوته كان متوسط الى مرتفع.\nالكويزات: كانت سهله ومن ثاني كويز كان يخليه اوبن بوك وكمان ممكن يجاوب عالسؤال في الكويز اذا سألته.\nالميجر: صراحه كانت تجي زي الاولد اكزامز من ناحية المسائل وقليل من الاختيارات عشان كذا كان الافرج في السبعينات\nالفايننل: كان صعب صراحة بس الحمدلله طلعت بالقريد اللي أبغاه بأقل مجهود بفضل الله ثم بفضل نعمان\nاضافه: في الصيف كانت غيباتي كثيييييره تقريبا 9 غيابات والحمدلله ما أعطاني دي ان وﻻ خصم علي، طبعن ياشباب أنا ما أقول كذا عشان اشجعكم عالغياب ممكن يعطيك دي ان لو شافك منت مهتم او ما عرفك.\nالقريد النهائي:+++++++A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1335776-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/numan-abu-dheir/98233/20", "user": "HANDSOME_THIEF", "ts": 1393745000000, "tid": 98233, "pn": 20}}]}', 1393745000000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ak-95-me322', 'stk-ak-95', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98233", "n": "Dr. Numan Abu-Dheir", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME-322 term 152\n\nالتحضير :\nغالبًا نهاية الكلاس ينادي على الأسماء وأحيانًا في البداية، ما يدقق عالتأخير كثير\n\nطريقة الشرح :\nسلايدات، والمادة بطبيعتها طوييييييلة وفيها حفظ كثير، بالتالي ما ألوم الدكتور إذا كان الكلاس كله كلام وشرح ممل.\nممكن ألومه في شغلة وحدة، وهي رغم أن المادة تقريبا 70% حفظ و 30% حل مسائل، لكن في المياجر والفاينال تصير المسائل تقريباً 60% و الأسئلة النظرية 40% ، بالتالي التركيز يكون أكثر على المسائل ، والدكتور ما يحل مسائل كثير ولا يركز عليها، يشوف إنها سهلة ومباشرة، وأغلبها كذلك بس لازم على الأقل الطالب يكون عنده فكرة عن طريقة الحل\n\nالكويزات :\nسهلة جدًا، تقريبًا كلها نسخ لصق من الكتاب، ويعطي تقريبا 7-8 كويزات ، وياخذ أفضل 5 ، من ناحية الكويزات ما عليه كلام أبدًا\n\nالمياجر ، الفاينلات :\nكومون ، وأشوفها بالعموم سهلة ، مثل ما ذكرت أن أغلب الأسئلة حل مسائل، وأغلب المسائل ما تطلع من الهومووركات أو الأولد اكزامز، لازم تطلع عليهم قبل لا تدخل الاختبار\n\nالقريد النهائي:\nA\n\nالصوت:\nواضح واللغة مفهومة\n\nإضافات :\nالدكتور ربما يكون شديد في الكلاس ، بس دمه خفيف ويمزح كثير 👍، تصحيحه في الكويزات و المياجر ممتااااااز جدًا يعطيك فوق حقك 👏، والمادة بطبيعتها سيلف ستدي ، أشوفه من أفضل الخيارات لهاذي المادة إن لم يكن أفضلهم 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1454548-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/numan-abu-dheir/98233/22", "user": "AK-95", "ts": 1469789548000, "tid": 98233, "pn": 22}}]}', 1469789548000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-r.a-me322', 'stk-r.a', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98236", "n": "Dr. Khaled Mezghani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 322 TERM 182\n\nالتحضير : يوميًا بداية الكلاس ويمنع اذا تأخرت تروح تكلمه نهاية الكلاس و راح يحضرك.\n\nطريقة الشرح : المادة نفسها مملة لإنها عبارة عن سلايدات … لكن نبرة صوته الواحدة يزيدها ملل.\n\nالكويزات : متوسطة مائلة إلى السهولة وتكون دائما Numerical.\n\nالمياجر: كومون … 50% Numerical و 50% MCQs.\n\nالفاينلات : كومون ونفس طريقة المياجر.\n\nالقريد النهائي: B+\n\nالصوت: منخفض نوعا ما ونبرة واحدة.\n\nإضافات :\n- بداية الترم تشعر ان الدكتور غير متعاون لكن في النهاية راح تكتشف غير ذلك.\n- في الاوفيس جدا متعاون و ياخذ و يعطي معاك.\n- تصحيحه في النيوميركال جدا ممتاز يعني اذا كانت مادة ستاندرد مثل ME216 راح يكون خيار ممتاز وبقوة.\n- ما يخصم على الغياب كما هو مكتوب بالسيلبس لكن يضع عدد الغيابات بعين الإعتبار.\n- مرتب ونهاية الترم راح يرفع ملف فيه كل الدرجات من مياجر و كويزات و هومووركات.\n- غير متعاون في مواعيد تسليم الهومووركات كان يقول آخر موعد للتسليم الساعة 1:00 PM وبعد كذا ما يقبل الهوموورك وفي ذا الكورس كل هوموورك عليه 2.5%.\n- رفع الفاينال قريد في البلاكبورد من غير درجة الفاينل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509137-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-mezghani/98236/21", "user": "R.A", "ts": 1556529483000, "tid": 98236, "pn": 21}}]}', 1556529483000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahm2d1-me322', 'stk-ahm2d1', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98236", "n": "Dr. Khaled Mezghani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 322 - 192\n\nالتحضير : يوزع ورقة بداية الكلاس او يحضر بنفسه ( على حسب النفسيه )\nطريقة الشرح : يفتح سلايداته ويشرح منها ، شرحه سيء وصوته مايتغير ويجيب النوم.\nالكويزات : كويزاته بعضها وسط وبعضها صعب ( تحتاج مذاكره كويسه )\nالمياجر: تصحيحه في الميجر سيء.\nالصوت: صوته خفيف ومايغير صوته ويجيب النوم\nإضافات : ابدا ما انصحكم فيه ، سجل عند اي واحد غيره. الدكتور اخلاقه سيئه ، بالنسبه للكويزات هو يختار يوم من كيفه ويرسل قبلها بيوم او يومين ويقول كويز ولا يناقش فيها احد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521703-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-mezghani/98236/23", "user": "Ahm2d1", "ts": 1588359009000, "tid": 98236, "pn": 23}}]}', 1588359009000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-me322', 'stk-guest', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98236", "n": "Dr. Khaled Mezghani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "me322 ترم 201 “ترم الاون لاين”\n\nاول شيء لازم اقوله انه هذا الترم المادة كلها عبارة عن “اوبن بوك/اوبن نوتس” يعني عادي تفتح سلايدات بجهازك وقت الاختبار\nالتحضير : من نظام البلاك بورد\nطريقة الشرح : يفتح سلايداته ويتكلم بطبقه صوت وحده تجيب الملل … ما تقدر تكمل تركيز طول المحاضرة\nسلايداته تعتبر سيئه وما فيها مسائل محلوله والصور فيها قليلة “المادة تحتاج صور كثير لفهم المكتوب” … المادة تمشي سيلف ستدي عمومًا\nالكويزات : كان اجباري عليه يحط 12 كويز كل واحد 3% و3 تيستات 5% وهو ما كان عاجبه هالنظام ابدًا ويطير وقت كلاسات كثير …\n6 كويزات كونسبت … مستواهم اعلى بشيء بسيط من المد والفاينل “ياخذ افضل 5”\n6 كويزات حل مسائل … مستواهم من مستوى المد والفاينل واحيان يجيب نفس افكار الاسئلة اللي حلها بالكلاس\n3 تيستات … تكون طول وقت الكلاس جزء منها نظري وجزء مسائل … مستواها معقول\nالمد تيرم: مستواه معقول وحاله حال اي ترم … اسئلة الكونسبت اغلبها من سلايدات سرحان والباقي بالكتاب\nالفاينلات : نفس المد تيرم … غير ان اسئله الحل اصعب نوعًا ما بحكم كثره القوانين للفاينل “الفاينل مو كومبرهنسڤ”\nالقريد النهائي: A\nإضافات : الدكتور متفهم للطلاب واتفقنا معه على امور كثير خلال الترم وكان متعاون جدًا معنا … اللي يبغى المادة سلف ستدي فهو خيار لا باس فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527488-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khaled-mezghani/98236/24", "user": "Guest", "ts": 1609592967000, "tid": 98236, "pn": 24}}, {"id": "stk-dr-f175788", "n": "Dr. Mobeen Shaukat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Me322- term 201\n\nالتحضير : كان يحط تصويت بالبلاكبورد في نص الكلاس ولا يعلمنا انه حط فاللي مركز بيحضره\nطريقة الشرح : المادة طويلة و اغلبها ينحفظ فما كنت اركز معه و بالنسبة للنيوميريكال شرحه ما اعجبني لانه كان يحل بالماوس\nالكويزات : سهلة\nالمياجر: كومون\nالفاينلات :كومون\nالقريد النهائي: A\nالصوت: واضح\nإضافات : ثاني مرة اخذ مع الدكتور و لو شفته بعدين راح انزل عنده لاسباب كثيرة منها انه متعاون و اخلاقه عسل و تصحيحه عسل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527554-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mobeen-shaukat/175788/8", "user": "Guest", "ts": 1609775457000, "tid": 175788, "pn": 8}}]}', 1609592967000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-amrfa-me322', 'stk-amrfa', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98242", "n": "Dr. Mohiuddin Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 322 - Term 131\n\nالتحضير في بداية كل محاضرة ينادي بالاسماء مرتين, و ما اعتقد ان عنده ليت لاني كنت احضر متأخر و يسجل قدام اسمي علامة صح زيي زي اي واحد جا بدري . و بالاضافة يمديك تتفق معاه تحضر مع سكشن ثاني اذا كان عنده اكثر من سكشن (بشرط تحضر باقي الكلاسات بالسكشن الثاني) << بالبداية يدقق بس بعد ميجر 2 ما يهتم ابدا\n\nالشرح : انا ما اهتم معاه بالمحاضرة لأن المادة كلها كلاااااااااام بس عنده حركة حلوة , يحل مسائل مو بس يشرح و يقرا من السلايدات .\n\nصوته مسموع و واضح 90%\n\nعنده حول ال6 كوزات و 6 هومووركات (5 او 6 ما افتكر << قبل شوي مخلص الترم XD)\n\nاضافات : الدكتور انصح فيه صراحة (و انا طالب آآفرج في كلاسه)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1316121-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mohiuddin-ahmed/98242/9", "user": "amrfa", "ts": 1389018036000, "tid": 98242, "pn": 9}}]}', 1389018036000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mkd-me322', 'stk-mkd', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98242", "n": "Dr. Mohiuddin Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السمستر والمادة: ME 322 - Term 171\n\nالتعامل: عادي ، شخصيا كان التعامل معي غير عن الثانين صار بيني وبينه موقف وبدا الموضوع يستهبل ، لكن أمانة بغض النظر عني المدرس تعاملة جدا عادي لا تتوقع ابتسامة على الساعة 8 الصباح لو ايش\n\nالصوت: واضح تسمعه من كلاس الكلاس\n\nالشرح: يحاول يشد حيله قد ما يقدر لكن كنت أشوفه اقل من عادي ، المادة مملة وهو مكمل شرح ما يوقف ابد من اول الكلاس لين الأخير ، ما أِشوفه شريح أبد\n\nالتحضير: يوميا بداية الكلاس\n\nالتصحيح: حقك بتاخذه ، حاول تراجع مياجرك كلها وكويزاتك عادي جدا انه يغلط بالتصحيح ف لا تخلي شي الا وانت مراجعه\n\nالمياجر والفاينل (الاختبارات بشكل عام): كومن\n\nكويزاته وسط لا صعبة ولا سهلة حاول تضمن اللي بالبداية لانها أسهل من اللي قدام\n\nآخر كويز جانا صعب والافرج طايح اذكر ، بيعطيكم 5 كويزات وبياخذها كلها وما راح يحذف ولا واحد ، فلا تنتكب ولا تسمعون كلامه بعطيكم واحد وبحذف واحد ، حط ببالك ان كلها محسوبة حكم\n\nإضافات: شخصيا ما أنصح فيه أبد ، الرجال يحاول يشد حيله لكن الكلاس جدا ممل على غير فايدة ، دور على غيره الا اذا انت دافور وبتركز معه على كل حال ، اذا كذا موفّق ي بعدي ، اذا مستواك وسط أو نازل اهرب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504945-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-mohiuddin-ahmed/98242/10", "user": "MKD", "ts": 1547532788000, "tid": 98242, "pn": 10}}]}', 1547532788000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6685-me322', 'stk-user6685', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f98245", "n": "Dr. Muhammad Younas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم\nأخذت مع الدكتور يونس me 322 و me 002 و me 210\n\nالتحضير\nكان في البداية دائما\n\nالشرح\nمدرس شرحه ممتاز و واضح … المشكلة ان صوته هادي وعلى نفس الرتم تحس بالنعاس مهما ركزت 🙂\nلكن يهمه ان الطلاب يفهمون … من المدرسين اللي ينصح الطلاب بضمير الأب ويتمنى انهم يكونون افضل\n\nالكوزات\nكانت عادية اقرب للسهلة و بالعادة بعد المياجر او قبلها … المهم ينشب وقت المياجر\n\nالمياجر\nكانت كومن\n\nالقريدات والتصحيح\nاشوفه ينصف الطالب هذا اذا ما ساعده بزياده … من هالناحية ممتاز\n\nالقريد النهائي\na\n\nبالتوفيق ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1379728-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-muhammad-younas/98245/13", "user": "user6685", "ts": 1402680778000, "tid": 98245, "pn": 13}}]}', 1402680778000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullatif1994-me322', 'stk-abdullatif1994', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f103291", "n": "Dr. Sohail Akhtar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME322 Term142\nالتحضير : تقريبا يومي ويحضر بالسلايدات\nطريقة الشرح : يشرح على السلايدات وشرح السلايدات يكفي …\nالكويزات : 5-7 كويزات … مو ذاكر … لكن في النهاية ياخذ افضل 5\nالمياجر: كومن ( ويغيرها باللي يناسب طلابه )\nالفاينلات : كومن\nالقريد النهائي:A+\nالصوت: واضح …\nإضافات : الصراحه الدكتور طيب ويدف شوي في القريدات والتصحيح", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449916-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/sohail-akhtar/103291/11", "user": "Abdullatif1994", "ts": 1463846407000, "tid": 103291, "pn": 11}}]}', 1463846407000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kemooo-me322', 'stk-kemooo', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f118643", "n": "Dr. Fadi Al-Bedoor", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "يلوموني فيك يا دكتور فادي :o\n<3 <3\nME322 152\n\nالتحضير : يحضر كل نهايه كلاس … مرا احسه يختبر الطلاب يعني مثلا احيانا في طلاب يجو متاخرين … تلقاه اخر الكلاس يسال اللي دخل متاخر يقول متاخر … ع كل حال الدكتور متفهم انا كنت اجيه من مبنى 24 الى عنده وكل كلاس اتاخر وتفهم … غير كدا يسمح انك تحضر السكشن الثاني اهم شي خليك اخلاق مع الدكتور !!!\n\nطريقة الشرح : الماده احيانا فيها دروس تجيب الملل فتلقاني استنى الخراج … شرح الدكتور من السلايدات يشرح لك كل سلايد … من كثر المعلومات مرات تطفش … شرحه طيب بس احيانا احسه يستعجل في حل المسائل لو انه يهدي فيها اكثر افضل …\nالكويزات : كويزاته سهله اذا انتا مذاكر … اغلبها زي المانيوال حق 4th edition … او يغير ارقام … حل كل الاسئله وحتجيب فل\n\nالمياجر: كومن بس تصحيحه يالبى قلبه والله\nالفاينلات : لسى ما اختبرت الفاينل باقيله 4 ايام لكن من دحين اقلكم … غمض عينك ونزل معاه\nالقريد النهائي: S+ هذا اعلى من الـ A+\nالصوت: واضح جداا جداا\nإضافات : ممكن تمل في الكلاس صح لكن … الدكتور فاهم ويجاوبك ع اي سؤال ومتعاون جدا جدا جدا حتى بالايميل ارسله ويرد عليا واساله ويرد , شبابي الدكتور ومحترم والله اني احبه وياريتني ميكانيكال ههههههههههه خساره اندستريال انجنيرينق\n\nخليك مهتم معاه وحيكون متعاون معاك … > something common between most of the doctors\n\nبالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1448251-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fadi-al-bedoor/118643/12", "user": "KeMoOo", "ts": 1462552846000, "tid": 118643, "pn": 12}}]}', 1462552846000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_ali_20-me322', 'stk-abu_ali_20', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f118643", "n": "Dr. Fadi Al-Bedoor", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME322\nTerm : 152\nالتحضير : تقريبا دائما يحضر , ويسمح تحضر في سكشن ثاني\nطريقة الشرح : يشرح من السلايدات شرح ممتاز لكن المادة أصلا ما تحتاج شرح كثير , تحتاج قراءة الكتاب أول بأول لأن المنهج مررررره طويييل\nالكويزات : سهلة دائما من أسألة الكتاب أو الهومورك\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: +A\nالصوت: واضح جدااا\nإضافات :\n\nمن أفضل الدكاترة الي مروا عليي … أخلاق عالية جدا … شرح روعة … فاهم المادة تمام …\nلكن للأمانة المادة فيها كلام كثييييييييير فأحيانا المحاضرة تكون مملة …\nالزبدة أنا اندستريال… لكن نصيحة من تشوف اسمه نزل عنده وانت مغمض …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1448582-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fadi-al-bedoor/118643/13", "user": "ABU_ALI_20", "ts": 1462915754000, "tid": 118643, "pn": 13}}]}', 1462915754000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dyaa94-me322', 'stk-dyaa94', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f118643", "n": "Dr. Fadi Al-Bedoor", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME322 - 152\n\nدكتور فادي خلوق جدا…\n\nكشرح u can’t really tell لأن الماده ممله ولا يحتاج لها شرح…تصحيحه شفته شديد في ميجر 1 وحلو بميجر 2 والفاينل ماعطانا الدرجات\n\nفي النهاية اذا بتنزل 322 ما أنصحك لأن الدكتور افرجه عالي وبيمشي عالستاندرد وفي النهاية ماراح يعجبك الفاينل قريد…نزل عند واحد نظامه غير…الشباب مثلا عند مبين والافرج B غير فادي…\n\nمع ذلك كل الشكر للدكتور فادي ماقصر واحرجنا بأخلاقه…\n\nبالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1449993-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fadi-al-bedoor/118643/14", "user": "Dyaa94", "ts": 1463912736000, "tid": 118643, "pn": 14}}]}', 1463912736000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-human-me322', 'stk-human', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f118648", "n": "Dr. Mohammed Abdulsamad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\n\nالتحضير :كان يمرر الورقه و احنا ما ننعطى وجه صار يحضر بعد خمس دقايق\nطريقة الشرح :فوق الممتاز بالنسبه اللكونسبت و المسائل\nالكويزات :عباره عن سؤال به لحسه صغييييييره ومجموعه من الاختيارات الليه و مسويها بنفسه بعض الاحيان تكون من خارج السلايدات حقته\nالمياجر:كومن و تصحيحه بالملي على قولته\"to be fair with everybody\"\nالفاينلات :^^\nالقريد النهائي:A+ <<<< اتحدى احد مايعطيه A+<<<حقه بالراحه\nالصوت:واضح جدا جدا جدا\nإضافات :ماشاء الله عليه ممتاز جدا (اول مره يدرس ME 322 … TERM 112)(الاستاذ اضافه جيده لقسم الهندسه الميكانيكيه )و\n\nسلايداته فوق الممتازه و انصح كل الطلاب ياخذو سلايداته سواءا يدرسوا عنده ولا لا …هو سنغافوري\n\n…لهجته واضحه جدا… اي شي يجيك في الاختبار حتلاقيه مفهمك عليه قبل الاختبار …شرحه ما يجيب النوم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1043410-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-abdulsamad/118648/2", "user": "HUMAN", "ts": 1337838392000, "tid": 118648, "pn": 2}}]}', 1337838392000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-iahmed015-me322', 'stk-iahmed015', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f118648", "n": "Dr. Mohammed Abdulsamad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME322 - T131\n\nالتحضير :\nكُل كلاس.\n\nطريقة الشرح :\nيشرح زي العالم والناس يوقف ويمشي مع سلايداته ويحل حسب الحاجة، شرحه جدًا بطل وإذا مافهمت منه العيب منك لأنك ماركزت.\n\nالكويزات :\nمستواها متوسط، غالبًا سؤال نيوميركال عليه 10 بوينتس واختيارات عليها 10 بوينتس كل كويز من 20 ، ويحذف كويز واحد آخر السمستر اذا عدى 5 مدري 6 كويزات.\n\nالمياجر:\nكومون\n\nالفاينلات :\nكومون\n\nالقريد النهائي:\na+\n\nالصوت:\nواضح جدًا وعالي ، وصوته يشدّك عشان تركز.\n\nإضافات :\nأنصح فيه وبششششششّدة الدكتور مهتم ويرد على الايميل بسرعة خيالية وتقدر تسأله عادي جدًا على الايميل، منظم ومتواجد في الاوفيس أور بكثرة، وطيب وخلوق.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1316640-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammed-abdulsamad/118648/5", "user": "iAhmed015", "ts": 1389099392000, "tid": 118648, "pn": 5}}]}', 1389099392000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman_780-me322', 'stk-abdulrahman_780', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f175788", "n": "Dr. Mobeen Shaukat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Semester:171\nME322\n\nبنود التقييم :\n\nالتحضير :\nالدكتور يحضر في نهاية كل كلاس ومسموح لك تغيب 3 غيابات\nطريقة الشرح :\nالماده اصلا ممله لان كلها حفظ فما الومه لما يقرا من السلايدات, يحاول يشرح المعادلات والتركات الي ممكن تجي منها\nالكويزات :\n5 كويزات كلها محسوبه بس متوسطة الى سهلة , بس ذاكر الاولد كويز في ise zalt + الكويز الموجود في السلوشن مانيوال حق الكتاب\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالقريد النهائي:\nA+\nالصوت:\nواضح جدا\nإضافات :\nالله يجزاك خير يا دكتور مبين , شخص قمه في الاخلاق والحرص على الطالب\nالدكتور من افضل الدكاترة اللي درسوني لانه يهتم بفهم الطالب , ويحب الطلاب ويهتم لمصلحتهم\nالدكتور يحاول يربط لك المادة بامثلة من الواقع\n\nبالنسبة للقريدات حقك وزياده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485942-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mobeen-shaukat/175788/3", "user": "Abdulrahman_780", "ts": 1515656690000, "tid": 175788, "pn": 3}}]}', 1515656690000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-owheading-me322', 'stk-owheading', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f175788", "n": "Dr. Mobeen Shaukat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME322- term182\nبنود التقييم :\n\nالتحضير :\nيحضر بالأسماء\nطريقة الشرح :\nسيئة بالنسبة لي، يقرأ السلايدات وإذا يبغى يوضح يرسم شيء غير مفهوم ع البوربوينت بالفأرة، كانت طريقته سيئة جدًا يعني من ناحية الشرح أعطيه 4/10\nالكويزات :\nسهلة جدًا وفي الجيب\nالمياجر والفاينل:\nCOMMON وتصحيحه جيد جدًا\n\nالقريد النهائي:\nC+\nالصوت:\nجيد", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522441-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mobeen-shaukat/175788/7", "user": "OWHEADING", "ts": 1590689012000, "tid": 175788, "pn": 7}}]}', 1590689012000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-trad-me322', 'stk-trad', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f175788", "n": "Dr. Mobeen Shaukat", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME322-202\n(Online)\n\nالتحضير :\nيحضراخر الكلاس واحيانا مايحضر\n\nطريقة الشرح :\nيستخدم سلايداته وشرحه ممتاز ويعُتمد عليه في المذاكرة.\n\nالكويزات :\nمتوسطة الى صعبة, على كلامه انه خلاها صعبة عشان كثير كانوا يغشون وكان افرج الكويزات عالي جدا والقسم سوا له مشكلة عشان هالشي.\n\nالمياجر: كومن\nالفاينلات :كومن\n\nالقريد النهائي:ِA\n\nالصوت: واضح ومفهوم\n\nإضافات :\nالدكتور اخلاقه عالية جدا ومتعاون مع الطلاب بشكل كبير من ناحية الشرح وتاجيل الكويزات وشرحه جيد للامانة. تصحيحة في الميدتيرم كان جبار واخذت درجة ماكنت اتوقعها اما في الفاينل تصحيحه كان لك عليه. طبعا انصح فيه وبشدة اذا لقيته لا تفوته وطبعا المادة ثقيلة جدا فنصيحتي لك عزيزي الطالب ذاكرها اول باول ولا تفوت شي لانه كورس طويييييييييييل وسلامتكم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530039-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mobeen-shaukat/175788/11", "user": "Trad", "ts": 1621640303000, "tid": 175788, "pn": 11}}]}', 1621640303000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar_ali_bajabaau-me322', 'stk-omar_ali_bajabaau', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f181422", "n": "Dr. Ahmed Sarhan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 322 - 201\n(Online)\n\nالتحضير : عن طريق البلاكبورد بصيغة تصويت ويكون مرتين او ثلاثة متوزعة على فترات يمكن اول ربع ساعة وبعدها ب 20 دقيقة للتاكيد. يعني لازم تكون متابع الكلاس لانه في اي لحظة يحط التصويت. بس غالبا انه اذا سويت التصويت مرة واحدة بيحسبلك حضور بس لازم تتاكد منه اول.\n\nالصوت: صوته واضح جدا ويشرح بالانجليزي مع لهجة مصرية واضحة بس مفهومة، لا تشيل همها.\n\nطريقة الشرح : شرح اونلاين من سلايداته عن طريق البلاكبورد وصراحة شريح ويفهمك الكونسبت بذكر امثلة وعرض فيديوهات تعزز الفهم وكمان يشرح الأسئلة والامثلة المحلولة.\n\nالتصحيح: حقاني وبعض الاحيان يدف شوية ويمشي بحيث انه مايخصم كثير ع الخطا البسيط، طالما انه خطواتك صحيحة ومرتبة.\n\nالكويزات : كويزاته ع البلاكبورد وتكون اما اختيارات وصح وخطا (quiz) او بس مقالي ( numerical test). الخيارات يلعب في كلمات الكونسبت ويصير فيها تريكات لو انت مو فاهم عدل، بس اشوفها سهلة صراحة اذا انت فاهم ومركز وقت قراءة السؤال. اما بالنسبة للمقالي برضو سهل واحس انه مايقدر يجيب عليها تريكات لانه طبيعة المادة كونسبت والمقالي الي فيها بس عبارة عن تطبيق للقوانين، يعني تقدر تقول تعويض قوانين مباشرة بدون تريكات.\n\nالمياجر: كانت ميد واخذنا اختبارين وكانوا نفس مستوى الكويزات تقريبا او اصعب بشوية وكانت مزيج من الاختياري وصح وخطا ومقالي. صراحة مااعرف اذا كان كومن او لا، بس الظاهر انه كل دكتور يعطي الاختبار لفصله.\n\nالفاينلات : فاينل كان نفس مستوى الميدين\n\nإضافات : زي ماذكر اخوي في التقييم السابق واتفق معاه في جميع النقاط. فعلا دكتور حبوب وخلوووق بشكل رهيب ومتعاون وطيب لأبعد درجة. في رايي سجل عنده وانت مغمض.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527544-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-sarhan/181422/4", "user": "Omar_Ali_BajabaaU", "ts": 1609758415000, "tid": 181422, "pn": 4}}]}', 1609758415000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moh_ammed-me322', 'stk-moh_ammed', 'ME 322', 'doc', '{"docs": [{"id": "stk-dr-f181422", "n": "Dr. Ahmed Sarhan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ME 322 - Term 222\n\nالتحضير: الدكتور يعطيك 10 دقايق عشان تجي الكلاس بدون مايسجلك غياب أو تأخير، التحضير ياخذه بنهاية الكلاس.\n\nالشرح: يستخدم سلايداته وشرحه ممتاز ويتقبل الأسئلة جدا ويحث عليها. شرحه كله بالعربي باللهجة المصري (أحسن شيء).\n\nالكويزات: أخذنا 3 كويزات بس، يبي لك تذاكر زين عشان ماتضيعها، وهي سهلة إلى متوسطة…إذا مذاكر بتحل.\n\nإضافات:\n- الدكتور جدا متساعد بالمواعيد والتأجيل، أي شيء في يده ويقدر يأجله يأجله لو بغيتوا، بس أهم شيء تعطونه خبر بدري وماراح يقصر أبدا.\n- سلايدات الدكتور جيدة للمذاكرة بس ماتكفيك، لازم تخش على الواجب والاولد والأشياء هذي.\n- الدكتور حبيب ومتساعد بشكل عام وأنصح فيه.\n\nالقريد النهائي: A+ بالراحة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536767-me322", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmed-sarhan/181422/5", "user": "Moh_ammed", "ts": 1687089478000, "tid": 181422, "pn": 5}}]}', 1687089478000, 1794826871, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
